export const COUNTRIES: Country[] = [
  ...PINNED.map(([code, name]) => ({ code, name, flag: flagUrl(code) })),
  ...REST.sort((a, b) => a[1].localeCompare(b[1])).map(([code, name]) => ({
    code,
    name,
    flag: flagUrl(code),
  })),
]

export function getCountryByCode(
  code: string,
  locale = "en",
): Country | undefined {
  const row = COUNTRIES.find((c) => c.code === code)
  if (!row) return undefined
  const geo = countryByCode(code)
  return geo ? { ...row, name: geoLabel(geo, locale) } : row
}
